mapper.select:
SELECT emp_id, emp_name, gender, dept, post, salary, hire_date, status
FROM emp
WHERE emp_id = #{empId}

mapper.update:
UPDATE emp
emp_name = #{empName}, gender = #{gender}, dept = #{dept}, post = #{post}, salary = #{salary}, hire_date = #{hireDate}, status = #{status},
WHERE emp_id = #{empId}
